function toast(m){const t=$("#toast");t.textContent=m;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2600)}
function save(){try{localStorage.setItem("cbc_school",state.school);localStorage.setItem("cbc_favs",JSON.stringify(state.favorites));localStorage.setItem("cbc_ratings",JSON.stringify(state.ratings));localStorage.setItem("cbc_welcome_seen",state.welcomeSeen?"1":"0")}catch{toast("Local storage is unavailable on this browser.")}}
function saveOwnerDraft(){if(!state.user)return;try{localStorage.setItem(ownerDraftKey(state.user.uid),JSON.stringify(ownerListing))}catch{toast("Draft storage is unavailable on this browser.")}}
function loadOwnerDraft(user){try{ownerListing=JSON.parse(localStorage.getItem(ownerDraftKey(user.uid))||"{}")||{}}catch{ownerListing={}}}
function driveConnected(user){return !!user&&localStorage.getItem(driveStateKey(user.uid))==="1"}
function saveDriveConnection(user,connected){if(!user)return;try{localStorage.setItem(driveStateKey(user.uid),connected?"1":"0")}catch{}}
function normalizePublishedListing(b){return {...b,id:b.id,school:b.school||"",name:b.businessName||b.name||"",cat:b.category||b.cat||"",price:Number(b.priceFrom||b.price||0),loc:b.address||b.location||"",delivery:b.delivery||"By arrangement",rating:Number(b.rating||0),about:b.shortDescription||b.about||"",wa:b.whatsapp||b.wa||"",email:b.email||"",imageUrl:b.featuredImageUrl||b.imageUrl||"",website:b.website||"",description:b.description||"",hours:b.hours||"",priceRange:b.priceRange||"",productImages:Array.isArray(b.productImages)?b.productImages:[]};}
function selectedBusinesses(){if(!state.school)return [];return publishedListings.map(normalizePublishedListing).filter(b=>String(b.school).trim()===String(state.school).trim())}
function getBusiness(id){return selectedBusinesses().find(x=>x.id===id)||null}
async function loadPublishedListings(){if(publishedListingsLoaded||!state.school)return;try{const r=await fetch(`/api/storage/upload?action=list&school=${encodeURIComponent(state.school)}`);const d=await r.json().catch(()=>({}));if(r.ok&&d.ok){publishedListings=Array.isArray(d.listings)?d.listings:[];publishedListingsLoaded=true;renderAll()}}catch(e){console.warn("Published listings could not be loaded",e)}}
function productCarousel(b){const imgs=Array.isArray(b.productImages)?b.productImages.filter(Boolean):[];if(!imgs.length)return "";return `<div class="detail-section product-gallery"><div class="gallery-head"><div><span class="eyebrow">Gallery</span><h2>Products & services</h2></div><span class="muted">Swipe to explore · ${imgs.length}</span></div><div class="product-carousel">${imgs.map((src,i)=>`<div class="product-slide"><img src="${esc(src)}" alt="${esc(b.name)} product ${i+1}" loading="lazy" decoding="async"></div>`).join("")}</div></div>`}
function closeDrawer(){const d=$("#drawer"),b=$("#backdrop");d?.classList.remove("open");d?.setAttribute("aria-hidden","true");b?.classList.add("hidden")}
function businessImage(b,large=false){const src=b.imageUrl||b.image||"assets/icon-512.png";return `<img src="${esc(src)}" alt="${esc(b.name)}" loading="lazy" decoding="async"${large?' class="detail-image"':''}>`}
function effectiveRating(b){const local=state.ratings[b.id]||[];if(local.length)return local.reduce((a,v)=>a+Number(v),0)/local.length;return Number(b.rating||0)}
function waUrl(b){const n=String(b.wa||"").replace(/[^0-9]/g,"");return n?`https://wa.me/${n}?text=${encodeURIComponent(`Hello ${b.name}, I found your business on CampBiz.`)}`:"#"}
function card(b){const avg=effectiveRating(b);return `<article class="biz-card" data-business="${esc(b.id)}" tabindex="0" role="button"><div class="biz-image">${businessImage(b)}</div><div class="biz-card-body"><span class="eyebrow">${esc(b.cat)}</span><h3>${esc(b.name)}</h3><p>${esc(b.about)}</p><div class="biz-meta"><span>⭐ ${avg?avg.toFixed(1):"New"}</span><span>₦${Number(b.price||0).toLocaleString()}+</span></div></div></article>`}
function wireBusinessActions(root=document){root.querySelectorAll("[data-business]").forEach(el=>{const open=()=>openBusiness(el.dataset.business);el.onclick=open;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}}}) ;root.querySelectorAll("[data-fav]").forEach(el=>el.onclick=()=>{const id=el.dataset.fav;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();toast(state.favorites.includes(id)?"Saved to your businesses.":"Removed from saved businesses.");openBusiness(id)})}
function renderHome(){const list=selectedBusinesses();const fyp=$("#fyp"),name=$("#campusName");if(name)name.textContent=state.school||"Choose your school";if(fyp)fyp.innerHTML=list.length?`<div class="grid">${list.map(card).join("")}</div>`:`<div class="empty-state"><h2>No published businesses yet</h2><p>There are no CampBiz listings published for <strong>${esc(state.school)}</strong> yet.</p><button class="primary" id="changeSchoolHome">Change school</button></div>`;$("#changeSchoolHome")?.addEventListener("click",goSchoolPicker);renderTools();wireBusinessActions()}
function renderResults(){const q=( $("#searchInput")?.value||$("#fypSearch")?.value||"").trim().toLowerCase();const cat=$("#categoryFilter")?.value||"";const price=$("#priceFilter")?.value||"";let list=selectedBusinesses().filter(b=>{const text=[b.name,b.cat,b.about,b.description,b.loc].join(" ").toLowerCase();if(q&&!text.includes(q))return false;if(cat&&b.cat!==cat)return false;const n=Number(b.price||0);if(price==='low'&&n>=3000)return false;if(price==='mid'&&(n<3000||n>10000))return false;if(price==='high'&&n<=10000)return false;return true});const out=$("#results");if(out)out.innerHTML=list.length?list.map(card).join(""):`<div class="empty-state"><h2>No matches</h2><p>Try another search or category.</p></div>`;wireBusinessActions(out||document)}
function renderFavorites(){const out=$("#favoritesGrid");const list=selectedBusinesses().filter(b=>state.favorites.includes(b.id));if(out)out.innerHTML=list.length?list.map(card).join(""):`<div class="empty-state"><h2>No saved businesses</h2><p>Save businesses from their view page to find them here.</p></div>`;wireBusinessActions(out||document)}
function populateCategories(){const s=$("#categoryFilter");if(s)s.innerHTML='<option value="">All categories</option>'+CATEGORIES.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join("");const m=$("#categoryMenu");if(m)m.innerHTML=CATEGORIES.map(c=>`<button type="button" class="menu-link category-link" data-category="${esc(c)}">${esc(c)}</button>`).join("");m?.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{location.hash='search';setTimeout(()=>{const s=$("#categoryFilter");if(s)s.value=b.dataset.category;renderResults();closeDrawer()},0)})}
function renderAll(){renderHome();renderResults();renderFavorites();if(location.hash==='#owner')renderOwnerDashboard()}
function goSchoolPicker(){const w=$("#welcomeScreen"),p=$("#schoolPicker"),a=$("#appLayout"),t=$("#topbar");w?.classList.add("hidden");a?.classList.add("hidden");t?.classList.add("hidden");p?.classList.remove("hidden");populateSchoolPicker()}
function showFirstVisit(force=false){if(force||!state.school){goSchoolPicker();return}$("#schoolPicker")?.classList.add("hidden");$("#welcomeScreen")?.classList.add("hidden");$("#topbar")?.classList.remove("hidden");$("#appLayout")?.classList.remove("hidden")}
function populateSchoolPicker(){
 const input=$("#schoolSelect"),drop=$("#schoolDropdown"),cont=$("#continueSchool");if(!input||!drop||!cont)return;
 let type="All";const types=["All",...Array.from(new Set(schools.map(s=>s.type))).sort()];const host=input.parentElement;
 let chips=host.querySelector(".school-type-chips");if(!chips){chips=document.createElement("div");chips.className="school-type-chips";chips.innerHTML=types.map(t=>`<button type="button" class="school-type-chip ${t==="All"?"active":""}" data-school-type="${esc(t)}">${esc(t)}</button>`).join("");host.appendChild(chips)}
 const render=()=>{const q=input.value.trim().toLowerCase();const matches=schools.filter(s=>(type==="All"||s.type===type)&&(!q||s.fullName.toLowerCase().includes(q)||s.abbr.toLowerCase().includes(q)||s.state.toLowerCase().includes(q))).slice(0,80);drop.innerHTML=matches.map(s=>`<button type="button" class="school-option" data-school="${esc(s.fullName)}"><strong>${esc(s.fullName)}</strong><small>${esc(s.abbr)} · ${esc(s.type)} · ${esc(s.state)}</small></button>`).join("")||'<p class="school-empty">No school found. Try a different name, abbreviation or state.</p>';drop.classList.remove("hidden");input.setAttribute("aria-expanded","true");drop.querySelectorAll("[data-school]").forEach(b=>b.onclick=()=>{input.value=b.dataset.school;state.school=b.dataset.school;cont.disabled=false;drop.classList.add("hidden");input.setAttribute("aria-expanded","false")})};
 chips.querySelectorAll("[data-school-type]").forEach(b=>b.onclick=()=>{type=b.dataset.schoolType;chips.querySelectorAll(".school-type-chip").forEach(x=>x.classList.toggle("active",x===b));render();input.focus()});input.onfocus=render;input.onclick=render;input.oninput=()=>{state.school="";cont.disabled=true;render()};cont.onclick=()=>{if(!state.school){toast("Choose your school first.");input.focus();return}state.welcomeSeen=true;save();$("#schoolPicker")?.classList.add("hidden");$("#welcomeScreen")?.classList.add("hidden");$("#topbar")?.classList.remove("hidden");$("#appLayout")?.classList.remove("hidden");publishedListingsLoaded=false;publishedListings=[];loadPublishedListings();renderAll();location.hash="home"};if(state.school){input.value=state.school;cont.disabled=false}
}

function route(){const hash=location.hash.replace('#','')||'';if(!state.school&&(hash==='home'||hash==='search'||hash==='favorites'||hash==='businessView'||hash==='')){goSchoolPicker();return}if(hash==='tools'&&state.school){showFirstVisit();}else if(hash==='owner'||hash==='home'||hash==='search'||hash==='favorites'||hash==='about'||hash==='businessView'){showFirstVisit();}else if(hash===''){showFirstVisit()}document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===hash));if(hash==='home'||hash==='')renderHome();if(hash==='search')renderResults();if(hash==='favorites')renderFavorites();if(hash==='owner')renderOwnerDashboard();if(hash==='businessView')wireBusinessActions();closeDrawer()}
function updateAccountUI(){const a=$("#drawerAccount");if(a)a.classList.toggle('hidden',!state.user);const owner=$("#ownerLogin");if(owner&&state.user)owner.classList.add('hidden');if(owner&&!state.user)owner.classList.remove('hidden')}
async function verifySubscriptionReturn(user){const params=new URLSearchParams(location.search);const reference=params.get('reference');if(!user||!reference||params.get('subscription')!=='trial-enroll')return;try{const token=await user.getIdToken();const r=await fetch('/api/subscription/trial-verify',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({reference})});const d=await r.json().catch(()=>({}));toast(d.message||d.error||'Billing setup completed.');history.replaceState({},'',location.pathname);updateOwnerAccess(user)}catch(e){toast('Could not verify the billing setup yet. Please try again.')}}
async function enrollTrialBilling(){const plan=document.querySelector('input[name="ownerPlan"]:checked')?.value||'monthly';const user=auth.currentUser;if(!user){toast('Sign in with Google first.');return}try{const token=await user.getIdToken();const r=await fetch('/api/subscription/trial-enroll',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({plan})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||'Unable to set up billing.');if(d.authorizationUrl)location.href=d.authorizationUrl;else toast(d.message||'Billing setup completed.')}catch(e){toast(e.message||'Unable to set up billing.')}}
async function activateTrialBilling(){const user=auth.currentUser;if(!user)return;try{const token=await user.getIdToken();const r=await fetch('/api/subscription/activate-trial',{method:'POST',headers:{Authorization:`Bearer ${token}`}});const d=await r.json().catch(()=>({}));toast(d.message||d.error||'Billing update complete.');updateOwnerAccess(user)}catch(e){toast('Unable to start billing automatically.')}}
async function startSubscription(){const plan=document.querySelector('input[name="ownerPlan"]:checked')?.value||'monthly';const user=auth.currentUser;if(!user){toast('Sign in with Google first.');return}try{const token=await user.getIdToken();const r=await fetch('/api/subscription/checkout',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({plan})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||'Unable to start Paystack checkout.');if(d.authorizationUrl)location.href=d.authorizationUrl;else toast(d.message||'Paystack checkout ready.')}catch(e){toast(e.message||'Unable to start subscription.')}}
function setup(){populateCategories();$("#searchBtn")?.addEventListener('click',renderResults);$("#searchInput")?.addEventListener('keydown',e=>{if(e.key==='Enter')renderResults()});$("#categoryFilter")?.addEventListener('change',renderResults);$("#priceFilter")?.addEventListener('change',renderResults);$("#fypSearch")?.addEventListener('keydown',e=>{if(e.key==='Enter'){location.hash='search';renderResults()}});const schoolSwitch=document.querySelector('.school-switch');schoolSwitch?.addEventListener('click',goSchoolPicker);showFirstVisit();}
function openBusiness(id){const b=getBusiness(id);if(!b)return;const related=selectedBusinesses().filter(x=>x.id!==id&&x.cat===b.cat);const other=selectedBusinesses().filter(x=>x.id!==id&&x.cat!==b.cat);const rel=[...related,...other].slice(0,6);const userRatings=state.ratings[b.id]||[];const avg=effectiveRating(b);const myRating=userRatings.length?userRatings[userRatings.length-1]:0;const starBasis=myRating||Math.round(avg);$("#businessViewContent").innerHTML=`<div class="detail-head"><button class="back-btn" onclick="location.hash='home'">← Back</button><span class="eyebrow">Business</span></div><div class="detail-hero"><div class="detail-img">${businessImage(b,true)}</div><div><span class="eyebrow">${esc(b.cat)}</span><h1>${esc(b.name)}</h1><p>${esc(b.about)}</p><p class="meta">📍 ${esc(b.loc)} · 🚚 ${esc(b.delivery)} · ⭐ ${avg.toFixed(1)}</p><div class="detail-actions"><a class="primary whatsapp" href="${waUrl(b)}" target="_blank" rel="noopener">Contact me on WhatsApp</a>${b.email?`<a class="email-btn" href="mailto:${esc(b.email)}">Email</a>`:""}<button data-fav="${esc(b.id)}">${state.favorites.includes(b.id)?"♥ Saved":"♡ Save"}</button></div></div></div><div class="detail-section"><h2>Business information</h2><div class="info-grid"><div><strong>Category</strong><span>${esc(b.cat)}</span></div><div><strong>Starting price</strong><span>₦${Number(b.price).toLocaleString()}</span></div><div><strong>Location</strong><span>${esc(b.loc)}</span></div><div><strong>Delivery</strong><span>${esc(b.delivery)}</span></div>${b.priceRange?`<div><strong>Price range</strong><span>${esc(b.priceRange)}</span></div>`:""}${b.hours?`<div><strong>Opening hours</strong><span>${esc(b.hours)}</span></div>`:""}${b.website?`<div><strong>Website</strong><span><a href="${esc(b.website)}" target="_blank" rel="noopener">Visit website</a></span></div>`:""}</div></div>${productCarousel(b)}${b.description?`<div class="detail-section"><h2>About this business</h2><p>${esc(b.description)}</p></div>`:""}<div class="detail-section"><h2>Rate this business</h2><p class="muted">Your rating is saved anonymously on this device.</p><div class="stars" role="radiogroup">${[1,2,3,4,5].map(n=>`<button type="button" data-rate="${n}" aria-label="Rate ${n} stars" aria-pressed="${n<=starBasis}">${n<=starBasis?"★":"☆"}</button>`).join("")}</div><small>${myRating?`You rated this ${myRating} star${myRating>1?'s':''} on this device · community average ⭐ ${avg.toFixed(1)}`:userRatings.length?`${userRatings.length} local rating${userRatings.length>1?'s':''}`:"Be the first to rate it on this device."}</small></div><div class="detail-section"><h2>Related businesses</h2><div class="grid">${rel.map(card).join("")||"<p>No related businesses yet.</p>"}</div></div>`;document.querySelectorAll("[data-rate]").forEach(x=>x.onclick=()=>{const n=+x.dataset.rate;state.ratings[b.id]=[...(state.ratings[b.id]||[]),n].slice(-20);save();toast("Thanks for rating this business.");openBusiness(b.id)});wireBusinessActions();location.hash="businessView"}
function renderTools(){const html=TOOLS.map(t=>`<div class="tool-card" data-tool="${t[2]}"><strong>${t[0]}</strong><span>${t[1]}</span></div>`).join("");$("#toolsGrid").innerHTML=html;$("#toolPreview").innerHTML=TOOLS.slice(0,4).map(t=>`<div class="tool-card" data-tool="${t[2]}"><strong>${t[0]}</strong><span>${t[1]}</span></div>`).join("");document.querySelectorAll("[data-tool]").forEach(x=>x.onclick=()=>openTool(x.dataset.tool))}
function openTool(type){const p=$("#toolPanel");p.classList.remove("hidden");const map={gpa:`<h2>GPA Calculator</h2><p>Add courses, units and scores.</p><div id="courseRows"></div><button class="actions" id="addCourse">＋ Add course</button><button class="primary" id="calc">Calculate GPA</button><div id="out"></div>`,cgpa:`<h2>CGPA Calculator</h2><p>Add every course/result you want included.</p><div id="courseRows"></div><button class="actions" id="addCourse">＋ Add course</button><button class="primary" id="calc">Calculate CGPA</button><div id="out"></div>`,percent:`<h2>Percentage Calculator</h2><input id="a" type="number" placeholder="Value"><input id="b" type="number" placeholder="Percent"><button class="primary" id="calc">Calculate</button><div id="out"></div>`,grade:`<h2>Target Score Calculator</h2><input id="total" type="number" placeholder="Total marks"><input id="current" type="number" placeholder="Marks already secured"><input id="target" type="number" placeholder="Target percentage"><button class="primary" id="calc">Calculate</button><div id="out"></div>`,timer:`<h2>Study Timer</h2><input id="mins" type="number" value="25" min="1"><button class="primary" id="start">Start</button><div id="out" class="tool-result">25:00</div>`,words:`<h2>Word Counter</h2><textarea id="txt" rows="8" placeholder="Paste or type your text..."></textarea><div id="out" class="tool-result">0 words · 0 characters</div>`,units:`<h2>Unit Converter</h2><input id="unit" type="number" placeholder="Value"><select id="from"><option>km</option><option>m</option><option>kg</option><option>g</option><option>C</option><option>F</option></select><select id="to"><option>m</option><option>km</option><option>g</option><option>kg</option><option>C</option><option>F</option></select><button class="primary" id="calc">Convert</button><div id="out"></div>`,deadline:`<h2>Deadline Countdown</h2><input id="date" type="datetime-local"><button class="primary" id="start">Start countdown</button><div id="out" class="tool-result">Choose a deadline.</div>`,notes:`<h2>Private Notes</h2><textarea id="notes" rows="12" placeholder="Your notes stay on this device."></textarea><div class="muted">Saved locally.</div>`};p.innerHTML=map[type]||"<h2>Tool unavailable</h2>";if(type==="gpa"||type==="cgpa"){const rows=$("#courseRows");const addRow=()=>{const row=document.createElement("div");row.className="course-row";row.innerHTML=`<input class="course-name" placeholder="Course"><input class="course-unit" type="number" min="0" step="0.5" placeholder="Units"><input class="course-score" type="number" min="0" max="100" placeholder="Score"><button type="button" class="remove-course">×</button>`;rows.appendChild(row);row.querySelector(".remove-course").onclick=()=>row.remove()};$("#addCourse").onclick=addRow;addRow();$("#calc").onclick=()=>{const scale=s=>s>=70?5:s>=60?4:s>=50?3:s>=45?2:s>=40?1:0;let units=0,points=0;rows.querySelectorAll(".course-row").forEach(r=>{const u=+r.querySelector(".course-unit").value,sc=+r.querySelector(".course-score").value;if(u>0&&sc>=0&&sc<=100){units+=u;points+=u*scale(sc)}});$("#out").innerHTML=units?`<div class="tool-result">${type.toUpperCase()}: ${(points/units).toFixed(2)}</div>`:`<div class="tool-result">Add valid course units and scores first.</div>`}}if(type==="percent")$("#calc").onclick=()=>$("#out").innerHTML=`<div class="tool-result">${((+$("#a").value||0)*(+$("#b").value||0)/100).toLocaleString()}</div>`;if(type==="grade")$("#calc").onclick=()=>{let need=((+$("#target").value||0)/100*(+$("#total").value||0))-(+$("#current").value||0);$("#out").innerHTML=`<div class="tool-result">Marks needed: ${Math.max(0,need).toFixed(2)}</div>`};if(type==="words")$("#txt").oninput=()=>{let s=$("#txt").value;$("#out").textContent=`${s.trim()?s.trim().split(/\s+/).length:0} words · ${s.length} characters`};if(type==="notes"){$("#notes").value=localStorage.getItem("cbc_notes")||"";$("#notes").oninput=()=>localStorage.setItem("cbc_notes",$("#notes").value)}if(type==="timer")$("#start").onclick=()=>{let sec=(+$("#mins").value||25)*60;const out=$("#out");const id=setInterval(()=>{sec--;out.textContent=`${String(Math.floor(sec/60)).padStart(2,"0")}:${String(sec%60).padStart(2,"0")}`;if(sec<=0){clearInterval(id);toast("Study session complete!")}},1000)};if(type==="deadline")$("#start").onclick=()=>{const target=new Date($("#date").value).getTime();if(!target||target<=Date.now()){toast("Choose a future deadline.");return}const out=$("#out");const id=setInterval(()=>{const d=target-Date.now();if(d<=0){clearInterval(id);out.textContent="Deadline reached.";return}out.textContent=`${Math.floor(d/86400000)}d ${Math.floor(d%86400000/36e5)}h ${Math.floor(d%36e5/6e4)}m ${Math.floor(d%6e4/1000)}s remaining`},1000)};if(type==="units")$("#calc").onclick=()=>{let v=+$("#unit").value||0,f=$("#from").value,t=$("#to").value,r=v;if(f==="km"&&t==="m")r=v*1000;if(f==="m"&&t==="km")r=v/1000;if(f==="kg"&&t==="g")r=v*1000;if(f==="g"&&t==="kg")r=v/1000;if(f==="C"&&t==="F")r=v*9/5+32;if(f==="F"&&t==="C")r=(v-32)*5/9;$("#out").innerHTML=`<div class="tool-result">${r.toFixed(3)}</div>`}}
function openAdComingSoon(){const m=$("#modal");const min=1000,max=100000,step=1000;m.innerHTML=`<div class="modal-card"><button class="modal-close" id="modalClose">×</button><span class="eyebrow">Sponsored advertising</span><h2>Coming soon</h2><p>Advertising will open after CampBiz has enough active users. The calculator below shows the planned pricing only.</p><div class="ad-preview"><label for="budgetRange">Budget</label><input id="budgetRange" class="vertical-range" type="range" min="${min}" max="${max}" step="${step}" value="10000"><div class="ad-numbers"><strong id="budgetValue">₦10,000</strong><span id="impressionValue">12,000 impressions</span></div><p class="muted">Planned rate: ₦1,000 per 1,200 impressions. Impressions are calculated from budget, not subscriber count.</p><button class="primary" disabled>Advertising unavailable</button></div></div>`;m.classList.add("show");$("#modalClose").onclick=()=>m.classList.remove("show");const r=$("#budgetRange");const update=()=>{$("#budgetValue").textContent=`₦${(+r.value).toLocaleString()}`;$("#impressionValue").textContent=`${(+r.value/1000*1200).toLocaleString()} impressions`};r.oninput=update;update()}
const OWNER_FREE_EMAIL="ilemobayotolulope11092003@gmail.com";
const TRIAL_MS=60*24*60*60*1000;
function ownerTrialKey(user){return `campbiz_owner_trial_${user.uid}`}
async function fetchBillingStatus(user){
 if(!user)return null;
 try{const token=await user.getIdToken();const r=await fetch("/api/subscription/status",{headers:{Authorization:`Bearer ${token}`}});return await r.json()}catch(e){console.error("Billing status failed",e);return null}
}
async function updateOwnerAccess(user){
 const btn=$("#subscribeAnnual"),dash=$("#ownerDashboard"),status=$("#subscriptionStatus");
 if(!user){btn.classList.add("hidden");dash.classList.add("hidden");status.textContent="Sign in with Google to create your business profile and start your free access.";return}
 loadOwnerDraft(user); renderOwnerDashboard();
 if((user.email||"").toLowerCase()===OWNER_FREE_EMAIL){dash.classList.remove("hidden");status.textContent="Lifetime free access is active.";return}
 btn.classList.remove("hidden");
 const billing=await fetchBillingStatus(user);
 ownerBillingStatus=billing||null;
 renderOwnerDashboard();
 if(billing?.active){status.textContent="Your Pro access is active.";btn.textContent="Billing active";btn.onclick=()=>toast("Your Paystack subscription is active.");return}
 if(billing?.trialActive){dash.classList.remove("hidden");const days=Math.max(1,Math.ceil((new Date(billing.trialEndsAt)-Date.now())/86400000));$("#trialStatus").textContent=`All Pro features free · ${days} day${days===1?"":"s"} remaining${billing.trialBillingReady?" · billing set up":""}.`;status.textContent=billing.trialBillingReady?"Your free trial is active and billing is ready for after the trial.":"Your 2-month Pro trial is active.";btn.textContent=billing.trialBillingReady?"Billing already set up":"Set up billing after trial";btn.onclick=billing.trialBillingReady?()=>toast("Billing is already set up."):enrollTrialBilling;return}
 if(billing?.trialBillingReady){btn.textContent="Start Pro billing";status.textContent="Your free trial has ended. Starting the selected recurring plan…";btn.onclick=activateTrialBilling;activateTrialBilling();return}
 dash.classList.remove("hidden");$("#trialStatus").textContent="Your 2-month free Pro trial has ended.";status.textContent="Choose a Paystack plan to continue with Pro features.";btn.textContent="Subscribe with Paystack";btn.onclick=startSubscription;
}

async function connectOwnerDrive(){
 const user=auth.currentUser;if(!user){toast("Sign in with Google first.");return}
 const btn=$("#connectDriveBtn");btn.disabled=true;btn.textContent="Connecting Google Drive…";
 try{
   const provider=new GProvider();provider.addScope("https://www.googleapis.com/auth/drive.file");
   const result=await reauthenticateWithPopup(user,provider);
   const credential=GProvider.credentialFromResult(result);const token=credential?.accessToken;
   if(!token)throw new Error("Google Drive authorization was not returned.");
   const idToken=await user.getIdToken();const verified=await fetch("/api/storage/upload",{method:"POST",headers:{Authorization:`Bearer ${idToken}`,"Content-Type":"application/json"},body:JSON.stringify({action:"connect",accessToken:token})});const vd=await verified.json().catch(()=>({}));if(!verified.ok||!vd.ok)throw new Error(vd.error||"CampBiz could not verify Google Drive.");saveDriveConnection(user,true);toast("Google Drive connected successfully.");renderOwnerDashboard();
 }catch(e){console.error("Drive connection failed",e);toast(e.message||"Google Drive connection failed.");}
 finally{btn.disabled=false;btn.textContent="Connect Google Drive"}
}

function listingValid(){const x=ownerListing;return !!(x.businessName&&x.school&&x.category&&x.shortDescription&&x.description&&x.priceFrom&&x.priceRange&&x.address&&x.hours&&x.whatsapp&&x.email&&x.featuredImageUrl&&x.confirmed)}
function renderOwnerDashboard(){const root=$("#listingWorkspace");if(!root)return;const user=auth.currentUser;if(!user){root.innerHTML=`<div class="dashboard-gate"><h2>Business owner access</h2><p>Sign in with Google first.</p><button class="primary" id="dashLoginBtn">Continue with Google</button></div>`;$("#dashLoginBtn").onclick=()=>$("#ownerLogin").click();return}if(!driveConnected(user)){root.innerHTML=`<div class="dashboard-gate"><div class="drive-icon">☁</div><span class="eyebrow">Step 2</span><h2>Connect Google Drive</h2><p>Your business dashboard is protected until you connect Google Drive. CampBiz uses Drive for your business media and storage workflow.</p><button class="primary" id="connectDriveBtn">Connect Google Drive</button><small class="muted">You can disconnect later from this device.</small></div>`;$("#connectDriveBtn").onclick=connectOwnerDrive;return}
const x=ownerListing;root.innerHTML=`<div class="dashboard-hero"><div><span class="eyebrow">Owner workspace</span><h2>Your CampBiz business dashboard</h2><p class="muted">Build once, save automatically, then publish to students at your selected school.</p></div><span class="drive-status">✓ Drive connected</span></div><div class="dashboard-steps"><div class="dashboard-step done"><b>1</b><span>Google account</span></div><div class="dashboard-step done"><b>2</b><span>Drive connected</span></div><div class="dashboard-step active"><b>3</b><span>Build listing</span></div><div class="dashboard-step"><b>4</b><span>Publish</span></div></div><div class="dashboard-summary"><div><strong>${esc(x.businessName||"New business")}</strong><span>${esc(x.school||state.school||"School not selected")}</span></div><div><strong>${Array.isArray(x.productImages)?x.productImages.length:0}</strong><span>gallery images</span></div><div><strong>${listingValid()?"Ready":"Draft"}</strong><span>listing status</span></div></div><div class="listing-form"><label>Business name<input id="lBusinessName" value="${esc(x.businessName)}" maxlength="80"></label><label>School<input id="lSchool" value="${esc(x.school||state.school)}" maxlength="120"></label><label>Category<select id="lCategory"><option value="">Select category</option>${CATEGORIES.map(c=>`<option ${x.category===c?"selected":""}>${esc(c)}</option>`).join("")}</select></label><label>Short description <small>Shown on feed</small><textarea id="lShort" maxlength="140">${esc(x.shortDescription)}</textarea></label><label>Full description<textarea id="lDescription" maxlength="1200">${esc(x.description)}</textarea></label><label>Featured image <small>Choose a photo from your device • CampBiz prepares it at 1280×720 (16:9) for the feed</small><input id="lImage" class="native-image-input" type="file" accept="image/jpeg,image/png,image/webp" hidden><button type="button" class="image-picker-btn" id="pickFeaturedImage">📷 Choose featured image</button></label><div id="imagePreview">${x.featuredImageUrl?`<img src="${esc(x.featuredImageUrl)}" alt="Featured preview">`:"<div class=\"image-upload-placeholder\">Your featured image will appear here</div>"}</div><div class="product-gallery-editor"><div class="gallery-editor-head"><div><strong>Product / service images</strong><small>Choose from your device. 1200×900 (4:3) keeps products clear and attractive in the view-page carousel.</small></div><span class="gallery-limit" id="productImageLimit"></span></div><input id="lProductImages" class="native-image-input" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden><button type="button" class="image-picker-btn" id="pickProductImages">🖼️ Add product images</button><div id="productImagePreview" class="product-thumb-grid">${(Array.isArray(x.productImages)?x.productImages:[]).map((src,i)=>`<div class="product-thumb"><img src="${esc(src)}" alt="Product image ${i+1}"><button type="button" data-remove-product="${i}" aria-label="Remove image">×</button></div>`).join("")}</div></div><label>Price from (₦)<input id="lPrice" type="number" min="1" value="${esc(x.priceFrom)}"></label><label>Price range<input id="lPriceRange" placeholder="e.g. ₦2,000–₦5,000" value="${esc(x.priceRange)}"></label><label>Address / location<input id="lAddress" value="${esc(x.address)}"></label><label>Opening hours<input id="lHours" placeholder="e.g. Mon–Sat, 8am–8pm" value="${esc(x.hours)}"></label><label>Delivery / service time<input id="lDelivery" value="${esc(x.delivery)}"></label><label>WhatsApp number<input id="lWhatsApp" type="tel" placeholder="2348012345678" value="${esc(x.whatsapp)}"></label><label>Email<input id="lEmail" type="email" value="${esc(x.email||user.email||"")}"></label><label>Website (optional)<input id="lWebsite" type="url" value="${esc(x.website)}"></label><label class="check"><input id="lConfirm" type="checkbox" ${x.confirmed?"checked":""}> I confirm these business details are accurate.</label><button class="primary publish-btn" id="publishListing" ${listingValid()?"":"disabled"}>Publish listing</button><p id="listingValidation" class="muted"></p></div>`;wireListingForm();updateProductImageLimit();updateListingValidation()}
function updateListingValidation(){const btn=$("#publishListing"),msg=$("#listingValidation");if(!btn)return;const missing=[];const labels={businessName:"business name",school:"school",category:"category",shortDescription:"short description",description:"full description",priceFrom:"starting price",priceRange:"price range",address:"location",hours:"opening hours",whatsapp:"WhatsApp",email:"email",featuredImageUrl:"featured image",confirmed:"confirmation"};Object.keys(labels).forEach(k=>{if(!ownerListing[k])missing.push(labels[k])});btn.disabled=missing.length>0;msg.textContent=missing.length?`Complete: ${missing.join(", ")}`:"Everything is ready to publish."}
async function compressImage(file,W,H,maxBytes=450*1024){return new Promise((resolve,reject)=>{const img=new Image();const url=URL.createObjectURL(file);img.onload=()=>{try{const scale=Math.max(W/img.naturalWidth,H/img.naturalHeight),sw=Math.round(W/scale),sh=Math.round(H/scale),sx=Math.max(0,Math.round((img.naturalWidth-sw)/2)),sy=Math.max(0,Math.round((img.naturalHeight-sh)/2));const c=document.createElement("canvas");c.width=W;c.height=H;const ctx=c.getContext("2d",{alpha:false});ctx.drawImage(img,sx,sy,sw,sh,0,0,W,H);const attempt=q=>c.toBlob(blob=>{if(!blob){URL.revokeObjectURL(url);return reject(new Error("Could not prepare that image."))}if(blob.size<=maxBytes||q<=0.62){URL.revokeObjectURL(url);return resolve(new File([blob],(file.name||"image").replace(/\.[^.]+$/i,"")+".jpg",{type:"image/jpeg",lastModified:Date.now()}))}attempt(Math.max(0.62,q-0.06))},"image/jpeg",q);attempt(0.86)}catch(e){URL.revokeObjectURL(url);reject(e)}};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error("That image could not be opened."))};img.src=url})}
async function prepareFeaturedImage(file){return compressImage(file,1280,720,450*1024)}
function ownerIsPro(){return !!((ownerBillingStatus?.active)||(ownerBillingStatus?.trialActive)||((auth.currentUser?.email||"").toLowerCase()===OWNER_FREE_EMAIL))}
function productImageLimit(){return ownerIsPro()?PRO_PRODUCT_IMAGE_LIMIT:FREE_PRODUCT_IMAGE_LIMIT}
function updateProductImageLimit(){const el=$("#productImageLimit");if(el)el.textContent=ownerIsPro()?`Pro · unlimited gallery`:`Free · ${FREE_PRODUCT_IMAGE_LIMIT} images`;const pick=$("#pickProductImages");if(pick)pick.disabled=(ownerListing.productImages||[]).length>=productImageLimit()}
async function prepareProductImage(file){return compressImage(file,1200,900,450*1024)}
function renderProductThumbs(){const el=$("#productImagePreview");if(!el)return;el.innerHTML=(Array.isArray(ownerListing.productImages)?ownerListing.productImages:[]).map((src,i)=>`<div class="product-thumb"><img src="${esc(src)}" alt="Product image ${i+1}"><button type="button" data-remove-product="${i}" aria-label="Remove image">×</button></div>`).join("");el.querySelectorAll("[data-remove-product]").forEach(btn=>btn.onclick=()=>{ownerListing.productImages.splice(+btn.dataset.removeProduct,1);saveOwnerDraft();renderProductThumbs();updateProductImageLimit()})}
async function uploadProductImage(file){const token=await auth.currentUser.getIdToken();const reader=new FileReader();const data=await new Promise((resolve,reject)=>{reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(file)});const r=await fetch("/api/storage/upload",{method:"POST",headers:{Authorization:`Bearer ${token}`,"Content-Type":"application/json"},body:JSON.stringify({fileName:file.name,mimeType:file.type,data})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||"Product image upload failed.");return d.publicUrl||d.webViewLink||(d.fileId?`https://drive.google.com/uc?export=view&id=${d.fileId}`:"")}
async function addProductImages(files){const list=Array.from(files||[]);const current=Array.isArray(ownerListing.productImages)?ownerListing.productImages:[];const room=Math.max(0,productImageLimit()-current.length);if(!room){toast(`Free listings allow ${FREE_PRODUCT_IMAGE_LIMIT} product images. Upgrade to Pro for an unlimited gallery.`);return}const selected=list.slice(0,room);if(selected.length<list.length)toast(`Only ${room} more product image${room===1?"":"s"} can be added to this listing.`);for(const file of selected){if(file.size>8*1024*1024){toast(`${file.name} is larger than 8 MB and was skipped.`);continue}try{const prepared=await prepareProductImage(file);const url=await uploadProductImage(prepared);if(url){ownerListing.productImages=[...(ownerListing.productImages||[]),url];saveOwnerDraft();renderProductThumbs();updateProductImageLimit()}}catch(e){console.error(e);toast(e.message||"Could not upload a product image.")}}}
function wireListingForm(){const map={businessName:"lBusinessName",school:"lSchool",category:"lCategory",shortDescription:"lShort",description:"lDescription",priceFrom:"lPrice",priceRange:"lPriceRange",address:"lAddress",hours:"lHours",delivery:"lDelivery",whatsapp:"lWhatsApp",email:"lEmail",website:"lWebsite"};Object.entries(map).forEach(([key,id])=>{const el=$("#"+id);if(!el)return;el.addEventListener("input",()=>{ownerListing[key]=el.value;saveOwnerDraft();updateListingValidation()});el.addEventListener("change",()=>{ownerListing[key]=el.value;saveOwnerDraft();updateListingValidation()})});$("#lConfirm").onchange=e=>{ownerListing.confirmed=e.target.checked;saveOwnerDraft();updateListingValidation()};$("#pickFeaturedImage").onclick=()=>$("#lImage").click();$("#lImage").onchange=async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>8*1024*1024){toast("Featured image must be 8 MB or smaller.");return}try{const prepared=await prepareFeaturedImage(file);const reader=new FileReader();reader.onload=()=>{$("#imagePreview").innerHTML=`<img src="${esc(reader.result)}" alt="Featured image preview">`};reader.readAsDataURL(prepared);ownerListing._imageFile=prepared;saveOwnerDraft();await uploadOwnerImage(prepared)}catch(err){console.error(err);toast(err.message||"Could not prepare that image.")}};$("#pickProductImages").onclick=()=>$("#lProductImages").click();$("#lProductImages").onchange=async e=>{await addProductImages(e.target.files);e.target.value=""};renderProductThumbs();updateProductImageLimit();$("#publishListing").onclick=publishOwnerListing}
async function uploadOwnerImage(file){try{const token=await auth.currentUser.getIdToken();const reader=new FileReader();reader.onload=async()=>{const data=String(reader.result);const r=await fetch("/api/storage/upload",{method:"POST",headers:{Authorization:`Bearer ${token}`,"Content-Type":"application/json"},body:JSON.stringify({fileName:file.name,mimeType:file.type,data})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||"Image upload failed.");ownerListing.featuredImageUrl=d.publicUrl||d.webViewLink||`https://drive.google.com/uc?export=view&id=${d.fileId}`;ownerListing.featuredImageId=d.fileId;delete ownerListing._imageFile;saveOwnerDraft();updateListingValidation();toast("Featured image saved to Drive.")};reader.readAsDataURL(file)}catch(e){console.error(e);toast(e.message||"Image upload failed.")}}
async function publishOwnerListing(){if(!listingValid()){toast("Complete all required listing information first.");updateListingValidation();return}const btn=$("#publishListing");btn.disabled=true;btn.textContent="Publishing…";try{const token=await auth.currentUser.getIdToken(true);const payload={id:`owner_${auth.currentUser.uid}`,businessName:ownerListing.businessName,school:ownerListing.school,category:ownerListing.category,shortDescription:ownerListing.shortDescription,description:ownerListing.description,priceFrom:Number(ownerListing.priceFrom),priceRange:ownerListing.priceRange,address:ownerListing.address,hours:ownerListing.hours,delivery:ownerListing.delivery||"By arrangement",whatsapp:ownerListing.whatsapp,email:ownerListing.email,website:ownerListing.website||"",featuredImageUrl:ownerListing.featuredImageUrl,featuredImageId:ownerListing.featuredImageId||null,productImages:Array.isArray(ownerListing.productImages)?ownerListing.productImages:[],confirmed:true};const r=await fetch("/api/storage/upload",{method:"POST",headers:{Authorization:`Bearer ${token}`,"Content-Type":"application/json"},body:JSON.stringify({action:"publish",listing:payload})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||"Could not publish listing.");ownerListing={...ownerListing,...payload,published:true,publishedAt:d.publishedAt||new Date().toISOString(),rating:0};saveOwnerDraft();publishedListings=[...publishedListings.filter(x=>x.id!==payload.id),normalizePublishedListing(payload)];publishedListingsLoaded=true;toast("Business published successfully.");renderAll();location.hash="home"}catch(e){console.error("Publish listing error",e);toast(e.message||"Could not publish listing.")}finally{btn.disabled=!listingValid();btn.textContent="Publish listing"}}
async function startGoogleAuth(source="welcome"){
 const btn=source==="owner"?$("#ownerLogin"):$("#googleSignIn"),status=$("#authStatus");
 if(auth.currentUser){$("#goDashboardBtn")?.classList.remove("hidden");location.hash="owner";route();return}
 if(btn)btn.disabled=true;if(status)status.textContent="Connecting securely to Google…";
 try{const mobile=/Android|iPhone|iPad|iPod/i.test(navigator.userAgent);if(mobile){await signInWithRedirect(auth,googleProvider);return}const result=await signInWithPopup(auth,googleProvider);state.user=result.user;try{localStorage.setItem("cbc_user",JSON.stringify({uid:result.user.uid,name:result.user.displayName||"",email:result.user.email||"",photoURL:result.user.photoURL||""}))}catch{}$("#goDashboardBtn")?.classList.remove("hidden");$("#googleSignIn")?.classList.add("hidden");if(status)status.textContent="Google connected. Continue to your dashboard.";if(source==="owner"){location.hash="owner";route();}}
 catch(error){console.error("Google sign-in error",error);const code=error?.code||"";if(code==="auth/popup-blocked"||code==="auth/operation-not-supported-in-this-environment"){try{await signInWithRedirect(auth,googleProvider);return}catch(redirectError){console.error(redirectError)}}const msg=code==="auth/unauthorized-domain"?"This website domain is not authorized in Firebase Authentication. Add it in Firebase Console → Authentication → Settings → Authorized domains.":code==="auth/popup-closed-by-user"?"Google sign-in was cancelled. Please try again.":"Google sign-in couldn't be completed. Please try again.";if(status)status.textContent=msg;toast(msg)}finally{if(btn)btn.disabled=false}}
$("#goDashboardBtn").onclick=()=>{if(!auth.currentUser){startGoogleAuth("welcome");return}location.hash="owner";route()};$("#ownerLogin").onclick=()=>startGoogleAuth("owner");
$("#menuBtn").onclick=()=>{$("#drawer").classList.add("open");$("#drawer").setAttribute("aria-hidden","false");$("#backdrop").classList.remove("hidden")};$("#closeMenu").onclick=closeDrawer;$("#backdrop").onclick=closeDrawer;document.querySelectorAll("#drawer nav a").forEach(a=>a.addEventListener("click",closeDrawer));$("#exploreBtn").onclick=goSchoolPicker;$("#schoolBack").onclick=()=>showFirstVisit(true);$("#skipToolsBtn").onclick=()=>{state.welcomeSeen=true;save();if(location.hash==="#tools")route();else location.hash="tools"};
  $("#googleSignIn").onclick=()=>startGoogleAuth("welcome");
  onAuthStateChanged(auth,user=>{state.user=user;updateOwnerAccess(user);verifySubscriptionReturn(user);updateAccountUI();if(user){$("#goDashboardBtn")?.classList.remove("hidden");$("#googleSignIn")?.classList.add("hidden");try{localStorage.setItem("cbc_user",JSON.stringify({uid:user.uid,name:user.displayName||"",email:user.email||"",photoURL:user.photoURL||""}))}catch{}}else{$("#goDashboardBtn")?.classList.add("hidden");$("#googleSignIn")?.classList.remove("hidden");try{localStorage.removeItem("cbc_user")}catch{}}});
  $("#signOutBtn").onclick=async()=>{
    try{if(auth.currentUser)await signOut(auth)}catch(error){console.error("Sign out error",error)}
    state.user=null;
    try{localStorage.removeItem("cbc_user")}catch{}
    save();
    $("#ownerLogin").textContent="Continue with Google";$("#ownerLogin").classList.remove("hidden");$("#goDashboardBtn")?.classList.add("hidden");
    $("#authStatus").textContent="";
    $("#subscriptionStatus").textContent="Google sign-in is required before subscribing.";
    updateAccountUI();
    closeDrawer();
    location.hash="home";
    route();
    toast("Signed out.");
  };
  getRedirectResult(auth).then(result=>{if(!result?.user)return;state.user=result.user;try{localStorage.setItem("cbc_user",JSON.stringify({uid:result.user.uid,name:result.user.displayName||"",email:result.user.email||"",photoURL:result.user.photoURL||""}))}catch{}$("#goDashboardBtn")?.classList.remove("hidden");$("#ownerLogin").classList.add("hidden");updateOwnerAccess(result.user);updateAccountUI();}).catch(error=>{console.error("Google redirect sign-in error",error);});$("#subscribeAnnual").onclick=startSubscription;$("#adMenu").onclick=openAdComingSoon;window.addEventListener("hashchange",route);setup();loadPublishedListings();route();
const rotating=["Find food, services and useful businesses around your school.","Compare campus services before you spend.","Save useful businesses for later.","Discover what students around you are using.","Get quick access to free student tools."];let rotateIndex=0;setInterval(()=>{const el=$("#rotatingText");if(!el||$("#welcomeScreen").classList.contains("hidden"))return;rotateIndex=(rotateIndex+1)%rotating.length;el.animate([{opacity:1,transform:"translateY(0)"},{opacity:0,transform:"translateY(8px)"}],{duration:180}).finished.then(()=>{el.textContent=rotating[rotateIndex];el.animate([{opacity:0,transform:"translateY(-8px)"},{opacity:1,transform:"translateY(0)"}],{duration:220})}).catch(()=>{el.textContent=rotating[rotateIndex]})},2800);
$("#fypSearch").oninput=e=>{if(e.target.value.trim()){$("#searchInput").value=e.target.value;renderResults()}};
